// Temporary one-factor experiments against current production shader.
export function candidateSources(source: string): [string, string][] {
  const replace = (text: string, from: string, to: string) => {
    if (!text.includes(from)) throw new Error(`Missing shader marker: ${from}`)
    return text.replace(from, to)
  }
  const kernel = 'vec4 m = max(0.6 - vec4(dot(x0,x0), dot(x1,x1), dot(x2,x2), dot(x3,x3)), 0.0);'
  let sparse = replace(source, kernel, '')
  sparse = replace(sparse, 'vec3 p0 = textureLod', `${kernel}\n    vec3 p0 = textureLod`)
  for (const [index, component] of ['x', 'y', 'z', 'w'].entries()) {
    const original = `vec3 p${index} = textureLod(uDustClumpGradients, (vec2(gx.${component}, gy.${component}) + 0.5) / 289.0, 0.0).xyz;`
    sparse = replace(sparse, original, `vec3 p${index} = vec3(0.0);\n    if (m.${component} > 0.0) p${index} = textureLod(uDustClumpGradients, (vec2(gx.${component}, gy.${component}) + 0.5) / 289.0, 0.0).xyz;`)
  }
  let hoist = replace(source,
    'float clumpGain = uDustClumpStrength * clamp(uDustClumpScale / (2.0 * dt), 0.0, 1.0);', '')
  hoist = replace(hoist, 'float dt = total / steps;', 'float dt = total / steps;\n          float clumpGain = uDustClumpStrength * clamp(uDustClumpScale / (2.0 * dt), 0.0, 1.0);')
  const zero = replace(source, 'if (clumpGain > 0.001)', 'if (clumpGain > 0.001 && contrib != 0.0)')
  const pairedPermutation = replace(source,
    'vec4 gy = dustClumpPermute(i.z + vec4(0.0, i1.z, i2.z, 1.0))',
    'vec4 zPerm = dustClumpPermute(i.z + vec4(0.0, 1.0, 0.0, 1.0));\n    vec4 gy = vec4(zPerm.x, i1.z == 0.0 ? zPerm.x : zPerm.y, i2.z == 0.0 ? zPerm.x : zPerm.y, zPerm.y)')
  return [['skipZeroKernelGradients', sparse], ['hoistClumpGain', hoist], ['skipZeroDensityNoise', zero], ['twoZPermutations', pairedPermutation]]
}

