import { candidateSources as initialVariants } from './dust-kernel-variants-2026-10-23'
export function candidateSources(source: string): [string, string][] {
  const vector4 = initialVariants(source).find(([name]) => name === 'twoZPermutations')![1]
  const vector2 = vector4
    .replace('vec4 dustClumpPermute(vec4 x)', 'vec2 dustClumpPermute(vec2 x)')
    .replace('vec4 p = ((x * 34.0) + 1.0) * x;', 'vec2 p = ((x * 34.0) + 1.0) * x;')
    .replace('vec4 zPerm = dustClumpPermute(i.z + vec4(0.0, 1.0, 0.0, 1.0));', 'vec2 zPerm = dustClumpPermute(i.z + vec2(0.0, 1.0));')
  if (!vector2.includes('vec2 dustClumpPermute(vec2 x)') || vector2.includes('vec4 zPerm')) throw new Error('Incomplete vec2 prototype')
  return [['twoZPermutationsVec4', vector4], ['twoZPermutationsVec2', vector2]]
}

