  const gl = renderer.getContext() as WebGL2RenderingContext
  const savedTarget = renderer.getRenderTarget(), savedAlpha = renderer.getClearAlpha()
  const savedColor = renderer.getClearColor(new Color()), savedAuto = renderer.autoClear
  const targets: WebGLRenderTarget[] = [], materials: ShaderMaterial[] = []
  const draw = renderer.render
  const blitMaterial = new ShaderMaterial({ glslVersion: GLSL3, uniforms: { map: { value: null } }, depthTest: false, depthWrite: false, blending: NoBlending,
    vertexShader: 'void main(){gl_Position=vec4(position.xy,0.0,1.0);}',
    fragmentShader: 'precision highp float; uniform sampler2D map; out vec4 fragColor; void main(){fragColor=texelFetch(map,ivec2(gl_FragCoord.xy),0);}' })
