      diagnostics: { covered, discarded, averageSteps: steps / covered, clumpsOff, minAlpha, maxAlpha, alphaBinEdges: edges, alphaBins } }
  } finally {
    renderer.render = draw
    for (const m of materials) m.dispose(); for (const target of targets) target.dispose()
    blit.geometry.dispose(); blitMaterial.dispose()
    renderer.setRenderTarget(savedTarget); renderer.setClearColor(savedColor, savedAlpha); renderer.autoClear = savedAuto
    engine.start()
  }
}

