    await page.evaluate(async () => (await import('/tests/browser/scenarioSoak.browser.ts')).returnToMenu())
    if (report.errors.length || report.warnings.length || report.assetFailures.length) throw new Error('Browser, shader or asset issue')
  }
  report.performanceGate = { minimumMedianReduction: 0.02, views: report.rows.flatMap(row => row.frozen.map(view => ({ id: row.id, translated: view.translated, baseline: view.summary.baseline.p50, optimized: view.summary.optimized.p50, ratio: view.summary.optimized.p50 / view.summary.baseline.p50 }))) }
  const misses = report.performanceGate.views.filter(view => view.ratio > 0.98)
  if (misses.length) throw new Error('Dust permutation performance gate: expected >=2% median reduction in every measured view; ' + JSON.stringify(misses))
  report.outcome = 'completed'
} catch (e) { report.failure = e.stack || e.message; console.error(e); process.exitCode = 1 }
finally { report.finishedAt = new Date().toISOString(); await writeFile(output, JSON.stringify(report, null, 2)); await browser?.close(); await server?.close() }

