const hash = bytes => createHash('sha256').update(bytes).digest('hex')
const decode = bytes => bytes[0] === 255 && bytes[1] === 254
  ? bytes.subarray(2).toString('utf16le') : bytes.toString('utf8').replace(/^\uFEFF/, '')
const normalize = text => text.replaceAll('\r\n', '\n')

async function source(path, json = true) {
  const bytes = await readFile(path)
  provenance.push({ path, bytes: bytes.length, sha256: hash(bytes) })
  const text = decode(bytes)
  if (text.includes('\0')) throw new Error(`Unexpected NUL in ${path}`)
  return json ? JSON.parse(text) : text
}
function browser(report) {
  const rows = []
  function walk(suite) {
    for (const child of suite.suites || []) walk(child)
    for (const spec of suite.specs || []) for (const test of spec.tests || []) for (const result of test.results || []) {
      const attachments = Object.fromEntries((result.attachments || [])
        .filter(item => item.body && item.contentType === 'application/json')
        .map(item => [item.name, JSON.parse(Buffer.from(item.body, 'base64').toString())]))
      const diagnostic = attachments['browser-diagnostics'], focused = spec.title.startsWith('dust ')
      rows.push({ title: spec.title, status: result.status, durationMs: result.duration, retry: result.retry, errors: result.errors,
        environment: focused ? attachments['webgl-environment'] : undefined,
        probe: focused ? attachments['probe-result'] : attachments['probe-result']?.status,
        diagnostics: diagnostic ? { pageErrors: diagnostic.pageErrors, failedRequests: diagnostic.failedRequests,
          warnings: diagnostic.warningClassifications, errors: diagnostic.console.filter(item => item.type === 'error') } : undefined })
    }
  }
  report.suites.forEach(walk)
  return { stats: report.stats, errors: report.errors, rows }
}
function timings(samples, summary) {
  const sorted = samples.slice().sort((a, b) => a - b)
  if (sorted.length !== 32 || summary.count !== 32 || sorted.some(value => !Number.isFinite(value) || value <= 0) ||
      sorted[15] !== summary.p50 || sorted[30] !== summary.p95 || sorted[31] !== summary.max) throw new Error('Invalid timing batch')
}
function cleanBrowser(run, expected) {
  if (run.stats.expected !== expected || run.stats.unexpected || run.stats.skipped || run.stats.flaky || run.errors.length ||
      run.rows.length !== expected || run.rows.some(row => row.status !== 'passed' || row.retry || row.errors?.length)) throw new Error('Incomplete browser run')
}
function views(run, requireImprovement) {
  if (run.rows.length !== 2 || run.errors.length || run.warnings.length || run.assetFailures.length) throw new Error('Unclean paired run')
  for (const scene of run.rows) {
    if (scene.frozen.length !== 2) throw new Error('Missing paired view')
    for (const row of scene.frozen) {
      for (const key of ['baseline', 'optimized']) timings(row.samples[key], row.summary[key])
      if (row.image.differentBits || row.image.maxError || !row.image.baselineRepeatIdentical || !row.image.sceneDepthIdentical ||
          row.outputSamples !== 8 || JSON.stringify(row.resources.before) !== JSON.stringify(row.resources.after)) throw new Error('HDR/depth/resource regression')
      if (requireImprovement && row.summary.optimized.p50 / row.summary.baseline.p50 > 0.98) throw new Error('Local performance gate failed')
    }
  }
}
